#!/usr/bin/env python3
# SPDX-License-Identifier: MIT. All counts and examples derive from native CSV files.
import csv,json,hashlib
from pathlib import Path
from collections import defaultdict
b=Path(__file__).resolve().parent
sets={}
for name,expected,edges in [('remainder',24,361),('scale',12,1920),('format',48,1937)]:
 d=defaultdict(dict)
 for r in csv.DictReader((b/'raw'/f'{name}-counts.csv').open()):d[(r['operation'],r['pc'],r['rounding'])][r['class']]=r
 assert len(d)==expected,(name,len(d))
 for k,v in d.items():
  assert int(v['ALL']['random'])==1000000,k
  assert int(v['ALL']['edge'])==edges,(name,k,v['ALL'])
  for r in v.values():assert int(r['total'])==int(r['random'])+int(r['edge'])
 hashes={}
 for suffix in ['counts','examples']:
  fn=f'{name}-{suffix}.csv';raw=(b/'raw'/fn).read_bytes();rep=(b/'validation'/f'{name}-repeat'/fn).read_bytes();assert raw==rep,fn
  hashes[fn]={'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'repeat_byte_identical':True}
 sets[name]={'status':'PASS','configurations':len(d),'random_cases':expected*1000000,'total_cases':sum(int(x['ALL']['total'])for x in d.values()),'files':hashes,'data':d}
with (b/'CANDIDATES-RESULT.md').open('w')as f:
 f.write('# Composite SSE2 candidates: remainder, scaling and formats\n\n')
 f.write('Every numerical arithmetic result is generated by native instructions in original MIT code. There is no libm, software-emulated x87 or external implementation. Integer control code selects IEEE fields, exact powers of two, loop branches and signs; these are explicitly composite algorithms, not nonexistent single SSE opcodes. PC24 uses binary32 sources, PC53/64 binary64, except the explicitly m80 load/store cases. All 84 configurations have one million random cases plus edges, each complete raw CSV reproduced byte-identically.\n\n')
 f.write('## FPREM and FPREM1\n\nThe reference records two separate executions from identical inputs: one architectural instruction with its observable partial result/FSW, and a loop to C2=0. The SSE candidate computes the completed mathematical remainder by scalar SUB: choose the largest exactly representable power-of-two multiple of abs(B) not exceeding the current remainder and subtract it. These subtractions are exact (operands within a factor of two); integer logic selects the divisor and tracks quotient magnitude mod8. FPREM1 uses an exact twice-remainder comparison and quotient parity to implement nearest-even quotient; a final SSE sign XOR restores dividend sign, including exact zero under RD. No FP quotient approximation or FMA is used.\n\n')
 f.write('The completed candidate cannot blindly replace one FPREM instruction: when x87 C2=1, the partial value and condition state are architecturally visible. The separate single-step columns below quantify that difference. A measured single-step C2=0 domain is separated explicitly. Quotient bits C0/C3/C1 correspond to magnitude Q2/Q1/Q0 on this hardware; signed-mod8 is retained only as a negative control.\n\n')
 fields=['VALUE_MISMATCH','FINITE_VALID_VALUE_MISMATCH','EXCEPTION_FLAGS_MISMATCH','X87_MULTISTEP','SINGLE_INSTRUCTION_VALUE_MISMATCH','SINGLE_INSTRUCTION_C2_PARTIAL','SINGLE_COMPLETE_FINITE_CASE','SINGLE_COMPLETE_FINITE_VALUE_MISMATCH','SINGLE_COMPLETE_QUOTIENT_DIFF']
 f.write('| Operation | PC | RC | Completed value differences | Completed finite differences | Exception-bit differences | Multi-step x87 cases | Single-instruction differences | Single C2 partial | Single-complete finite cases | Their value differences | Their quotient differences |\n|---|---:|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|\n')
 for k,d in sets['remainder']['data'].items():f.write('| '+' | '.join((*k,*(d[x]['total']for x in fields)))+' |\n')
 f.write('\nSome pairs require hundreds of scalar subtractions. This is a correctness candidate, not an optimized throughput proposal. x87 completion is capped at 128 iterations; any failure to clear C2 is separately counted. NaN propagation and load-related exception flags remain distinct.\n\n## FSCALE\n\nThe composite candidate truncates the exponent operand using integer inspection of its original IEEE encoding. It multiplies by exact normal powers of two with real MULSS/MULSD. For negative scales, the short residual factor is applied before large chunks; otherwise an unnecessary early subnormal rounding could change the final result. Finite scales outside +/-4096 are clamped for target IEEE saturation only: this is not equivalence to the broad x87 register exponent range. Infinite scale uses a native multiply by +infinity or +zero; NaN scale uses native multiplication by that NaN. All special cases remain measured, not presumed equivalent.\n\n')
 f.write('| PC | RC | Register differences | Exception-bit differences | NaN result cases | Above target max exponent | Below normal exponent | Narrowed value differences | Finite narrowed differences | Finite normal-reference differences |\n|---:|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|\n')
 fields=['REGISTER_VALUE_MISMATCH','EXCEPTION_FLAGS_MISMATCH','NAN_RESULT','ABOVE_TARGET_MAX_EXP','BELOW_TARGET_NORMAL_EXP','NARROWED_VALUE_MISMATCH','FINITE_NARROWED_VALUE_MISMATCH','FINITE_NORMAL_REFERENCE_MISMATCH']
 for k,d in sets['scale']['data'].items():f.write('| '+' | '.join((*k[1:],*(d[x]['total']for x in fields)))+' |\n')
 f.write('\nMultiple SSE multiplies can expose denormal intermediates and accumulate flags differently from one x87 FSCALE. Stored-value agreement does not authorize replacing an extended register value or ignoring these flags.\n\n## FXTRACT, FRNDINT and m80 format candidates\n\nFXTRACT finite nonzero inputs use the auxiliary IEEE decomposition plus real SSE MOV and CVTSI exponent conversion, comparing both significand and exponent. Zero uses a real SSE (-1)/0 for its -infinity exponent; infinity uses measured moves; NaN uses actual ADD with zero to quiet it. FRNDINT completes the auxiliary finite SSE2 conversion/identity algorithm with actual ADD-zero handling for infinity/NaN. This is an SSE2 composite path; the separate auxiliary ROUNDSD/SS experiment explicitly requires SSE4.1.\n\nFLD80/FSTP80 use an explicitly lossy proposed representation path: actual x87 FSTP narrowing of the existing m80 input to binary32/64, actual SSE move, actual expansion back to m80. Input-conversion FSW and expansion FSW are separate from SSE MXCSR. No nonexistent SSE m80 opcode is claimed. The original x87 m80 load/store identity is independently checked.\n\n')
 f.write('| Operation | PC | RC | Value differences | Native operation flags differ | Source conversion exceptions | NaN cases | Expansion exceptions | Original m80 identity changed |\n|---|---:|---|---:|---:|---:|---:|---:|---:|\n')
 fields=['VALUE_MISMATCH','NATIVE_OPERATION_FLAGS_MISMATCH','SOURCE_CONVERSION_EXCEPTION','NAN_RESULT','EXPANSION_EXCEPTION','LOADSTORE80_IDENTITY_CHANGED']
 for k,d in sets['format']['data'].items():f.write('| '+' | '.join((*k,*(d[x]['total']for x in fields)))+' |\n')
 f.write('\n## Conclusions\n\n- FPREM/FPREM1: unconditional replacement with completed remainder is invalid for observable C2=1 partial state. Finite completed values and the measured C2=0 subset are evaluated separately; see exact failure counts and status differences above\n- FSCALE: unconditional double/float register replacement is invalid because of extended exponent range and state differences; target-format stored values are a separate measured question\n- FXTRACT: both outputs were compared across finite values and specials; value agreement is distinct from flags and arbitrary m80 input support\n- FRNDINT: a composite SSE2 candidate was measured across the IEEE source domain including specials; this does not generalize to arbitrary pre-existing m80 precision/range\n- FLD/FSTP m80: a lossy IEEE representation path discards measured information and cannot replace exact 80-bit storage globally\n\nThese experiments characterize specific candidate algorithms on this CPU. No finite sample proves universal equivalence. Single-instruction x87 reference data in aux remain available even when a composite algorithm has different partial/state semantics.\n\n## Reproduction\n\nRun bash run-remainder.sh, bash run-scale.sh and bash run-format.sh; each defaults to one million cases per mode and accepts count then output directory. Detailed raw examples are raw/{remainder,scale,format}-examples.csv, with native hex outputs and FSW/MXCSR. validate-candidates.json records the full repeat comparison.\n')
for v in sets.values():del v['data']
(b/'validation/validate-candidates.json').write_text(json.dumps(sets,indent=2)+'\n');print(json.dumps(sets,indent=2))
